    /// <summary>
    /// List Fluent Icon Data
    /// </summary>
    /// <param name="types">Fluent Icon Types</param>
    /// <returns>Fluent Icon Data</returns>
    public static FluentIconData[] List(FluentIconType[] types) =>
        [.. types.Select(type => Data[type])];

    /// <summary>
    /// Get Fluent Icon Data
    /// </summary>
    /// <param name="type">Fluent Icon Type</param>
    /// <returns>Fluent Icon Data</returns>
    public static FluentIconData Get(FluentIconType type) =>
        Data[type];
